const banned = [
  /guaranteed win/i,
  /easy money/i,
  /risk[- ]?free/i,
  /beat the system/i,
  /sure profit/i
];
const imageB64 = $('OpenAI Generate Image').first().json.data?.[0]?.b64_json || null;
const source = $('Parse Image Prompt').first().json;
const englishJson = source.english_json || {};
const russianJson = source.russian_json || englishJson;
const fullEn = [
  englishJson.hook, englishJson.main_point,
  ...(englishJson.bullets || []), englishJson.closing,
  englishJson.x_hook, ...(englishJson.x_bullets || []), englishJson.x_cta
].join(' ');
const fullRu = [
  russianJson.hook, russianJson.main_point,
  ...(russianJson.bullets || []), russianJson.closing,
  russianJson.x_hook, ...(russianJson.x_bullets || []), russianJson.x_cta
].join(' ');
const hit = banned.find((re) => re.test(fullEn) || re.test(fullRu));
const disclaimerEn = source.disclaimer_en || ((typeof $env !== 'undefined' ? $env : {}).DISCLAIMER_PRIMARY || 'Educational content only. No guarantees.');
const disclaimerRu = source.disclaimer_ru || ((typeof $env !== 'undefined' ? $env : {}).DISCLAIMER_SECONDARY || (typeof $env !== 'undefined' ? $env : {}).DISCLAIMER_PRIMARY || 'Educational content only. No guarantees.');
const buildXText = (json, disclaimer) => {
  const hook = json.x_hook || json.hook || '';
  const bullets = (json.x_bullets || json.bullets || []).slice(0, 2).map(b => `• ${b}`).join('\n');
  const cta = json.x_cta || '';
  const full = `${hook}\n\n${bullets}\n\n${cta}\n\n${disclaimer}`;
  return full.length <= 280 ? full : full.slice(0, 277) + '…';
};
const pillar = source.pillar || 'pillar_a';
const topic = source.topic || '';
const baseHashtags = {
  pillar_a: (((typeof $env !== 'undefined' ? $env : {}).HASHTAGS_PILLAR_A || '#TagA1 #TagA2 #TagA3').split(' ')),
  pillar_b: (((typeof $env !== 'undefined' ? $env : {}).HASHTAGS_PILLAR_B || '#TagB1 #TagB2 #TagB3').split(' ')),
};
const topicHashtags = {
  // optional: map a topic keyword to extra tags
  // example_topic: ['#TagX1', '#TagX2'],
};
const universalHashtags = (((typeof $env !== 'undefined' ? $env : {}).HASHTAGS_UNIVERSAL || '#TagU1 #TagU2').split(' '));
const getHashtags = (pillar, topic) => {
  const base = baseHashtags[pillar] || baseHashtags['pillar_a'];
  const topicKey = Object.keys(topicHashtags).find(k => topic.toLowerCase().includes(k));
  const topicTags = topicKey ? topicHashtags[topicKey] : [];
  const all = [...base, ...topicTags, ...universalHashtags];
return [...new Set(all)].slice(0, 5).join(' ');
};
const hashtagsEn = getHashtags(pillar, topic);
const hashtagsRu = ((typeof $env !== 'undefined' ? $env : {}).HASHTAGS_SECONDARY_LANG || '#TagS1 #TagS2 #TagS3');

const buildIgCaption = (hook, mainPoint, closing, disclaimer, hashtags) => {
  const full = `${hook}\n\n${mainPoint}\n\n${closing}\n\n${disclaimer}\n\n${hashtags}`;
  if (full.length <= 500) return full;
  const withoutClosing = `${hook}\n\n${mainPoint}\n\n${disclaimer}\n\n${hashtags}`;
  if (withoutClosing.length <= 500) return withoutClosing;
  return `${hook}\n\n${disclaimer}\n\n${hashtags}`.slice(0, 500);
};

return [{
  json: {
    ...source,
    image_b64: imageB64,
    safe: !hit,
    safety_reason: hit ? `Matched banned pattern: ${hit}` : 'pass',
    x_text_en: buildXText(englishJson, disclaimerEn),
    x_text_ru: buildXText(russianJson, disclaimerRu),
    ig_caption_en: buildIgCaption(englishJson.hook, englishJson.main_point, englishJson.closing, disclaimerEn, hashtagsEn),
    ig_caption_ru: buildIgCaption(russianJson.hook, russianJson.main_point, russianJson.closing, disclaimerRu, hashtagsRu),
    hashtags_en: hashtagsEn,
    hashtags_ru: hashtagsRu
  }
}];

const src = $('Restore Pending Data').first().json;
const ig = $('Threads Publish').first().json;
return [{
  json: {
    post_uuid: src.post_uuid,
    published_at: new Date().toISOString(),
    scheduled_slot: src.scheduled_slot,
    topic: src.topic,
    pillar: src.pillar,
    x_post_id_en: null,
